cat > app.test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import test from 'node:test';

function exportCsv(values, variant) {
  return execFileSync(process.execPath, [
    new URL('./app.mjs', import.meta.url).pathname,
    JSON.stringify(values),
    ...(variant ? [variant] : []),
  ], { encoding: 'utf8' });
}

test('default preserves Unicode and column order while escaping CSV fields', () => {
  assert.equal(exportCsv(['東京', 'Lee, Sam', '', 'Zoë', 'say "hi"', 42]),
    '東京,"Lee, Sam",,Zoë,"say ""hi""",42\n');
});

test('quotes line breaks, including standalone carriage returns', () => {
  assert.equal(exportCsv(['a\nb', 'c\rd', 'e\r\nf']),
    '"a\nb","c\rd","e\r\nf"\n');
});

test('handles empty input and trailing empty columns', () => {
  assert.equal(exportCsv([]), '\n');
  assert.equal(exportCsv(['first', '', '']), 'first,,\n');
});

test('explicit component configurations remain available', () => {
  const values = ['Zoë', 'a,b'];
  assert.equal(exportCsv(values, 'full'), 'Zoë,"a,b"\n');
  assert.equal(exportCsv(values, 'baseline'), 'Zo,a,b\n');
  assert.equal(exportCsv(values, 'without-unicode'), 'Zo,"a,b"\n');
  assert.equal(exportCsv(values, 'without-escaping'), 'Zoë,a,b\n');
});
EOF
